contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address target, uint256 which) public {
        require(caller != address(0));
        require(target != address(0));

        uint256 callerWardBefore = c.wards(caller);
        uint256 targetWardBefore = c.wards(target);

        bool reverted;
        if (which % 2 == 0) {
            try c.rely(target) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (reverted) {
                assert(callerWardBefore != 1);
                assert(c.wards(target) == targetWardBefore);
            } else {
                assert(callerWardBefore == 1);
                assert(c.wards(target) == 1);
            }
        } else {
            try c.deny(target) {
                reverted = false;
            } catch {
                reverted = true;
            }

            if (reverted) {
                assert(callerWardBefore != 1);
                assert(c.wards(target) == targetWardBefore);
            } else {
                assert(callerWardBefore == 1);
                assert(c.wards(target) == 0);
            }
        }
    }
}

