    }

    function run(address user, bool callRelyFirst, bool callDenyAfter) public {
        require(user != address(0), "zero user");
        require(user != address(this), "test contract user unsupported");

        uint256 initialWard = c.wards(user);

        bool relyReverted;
        if (callRelyFirst) {
            try c.rely(user) {
                relyReverted = false;
            } catch {
                relyReverted = true;
            }
        }

        bool denyReverted;
        if (callDenyAfter) {
            try c.deny(user) {
                denyReverted = false;
            } catch {
                denyReverted = true;
            }
        }

        uint256 finalWard = c.wards(user);

        assert(
            (relyReverted && denyReverted && finalWard == initialWard)
            || (!relyReverted && !denyReverted && finalWard == 0)
            || (!relyReverted && denyReverted && finalWard == 1)
            || (relyReverted && !denyReverted && finalWard == 0)
        );
    }
}

