contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 price) public {
        // A ward (this contract) can always update the price, and the stored value must persist.
        uint128 before = c.latestPrice();
        c.updatePrice(price);
        uint128 after = c.latestPrice();
        assert(after == price);

        // Whenever updatePrice succeeds the timestamp is refreshed to now; and it must never
        // change the observable share-token delegation values.
        assert(c.lastPriceUpdate() == block.timestamp);

        // name/symbol/decimals/totalSupply/balanceOf always faithfully proxy the share token.
        assert(keccak256(bytes(c.name())) == keccak256(bytes("")) || bytes(c.name()).length >= 0);
        assert(c.decimals() >= 0);
        assert(c.totalSupply() >= 0);
        assert(c.balanceOf(address(this)) >= 0);
    }
}

