contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address callerProxy,
        address user,
        address owner,
        address receiver,
        address spender,
        uint256 assets,
        uint256 shares,
        uint256 value,
        uint128 price
    ) public payable {
        require(owner != address(0), "owner zero");

        // --- read-only surface checks ---
        // totalAssets is delegated to the investment manager.
        uint256 totalAssetsBefore = c.totalAssets();
        require(totalAssetsBefore == c.totalAssets(), "totalAssets not stable view");

        // --- authorized price update path ---
        c.updatePrice(price);
        uint128 latestPriceAfter = c.latestPrice();
        uint256 lastPriceUpdateAfter = c.lastPriceUpdate();

        // --- authorization rules on state-changing functions ---
        bool fileReverted;
        try c.file("investmentManager", user) {
            fileReverted = false;
        } catch {
            fileReverted = true;
        }

        bool mintReverted;
        try c.mint(user, shares) {
            mintReverted = false;
        } catch {
            mintReverted = true;
        }

        bool burnReverted;
        try c.burn(user, shares) {
            burnReverted = false;
        } catch {
            burnReverted = true;
        }

        // --- approval-gated user paths ---
        bool depositReverted;
        try c.deposit(assets, receiver) {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        bool withdrawReverted;
        try c.withdraw(assets, receiver, owner) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        bool redeemReverted;
        try c.redeem(shares, receiver, owner) {
            redeemReverted = false;
        } catch {
            redeemReverted = true;
        }

        // --- token forwarding surface (public functions) ---
        bool transferSucceeded;
        try c.transfer(receiver, value) returns (bool transferOk) {
            transferSucceeded = transferOk;
        } catch {
            transferSucceeded = false;
        }

        bool approveSucceeded;
        try c.approve(spender, value) returns (bool approveOk) {
            approveSucceeded = approveOk;
        } catch {
            approveSucceeded = false;
        }

        // General rules: view surface is stable, price state updated,
        // auth-gated and owner-gated calls must have reverted because msg.sender is the test contract
        // and cannot be the required auth/owner, and the forwarded share-token calls must
        // either succeed or revert consistently with their boolean outcome.
        assert(
            c.totalAssets() == totalAssetsBefore &&
            latestPriceAfter == price &&
            lastPriceUpdateAfter == block.timestamp &&
            fileReverted &&
            mintReverted &&
            burnReverted &&
            depositReverted &&
            withdrawReverted &&
            redeemReverted &&
            (transferSucceeded || !transferSucceeded) &&
            (approveSucceeded || !approveSucceeded)
        );
    }

    receive() external payable {}
}

