contract InvMutTest {
    C internal c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 amount) public payable {
        require(address(this) != from, "test must not be the sender");

        uint256 fromBefore = c.balanceOf(from);
        uint256 toBefore = c.balanceOf(to);
        uint256 supplyBefore = c.totalSupply();
        uint256 cBalanceBefore = address(c).balance;

        bool reverted;
        bool returned;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
            returned = ok;
        } catch {
            reverted = true;
            returned = false;
        }

        uint256 fromAfter = c.balanceOf(from);
        uint256 toAfter = c.balanceOf(to);
        uint256 supplyAfter = c.totalSupply();
        uint256 cBalanceAfter = address(c).balance;

        if (from != to) {
            assert(
                fromAfter == fromBefore - amount &&
                toAfter == toBefore + amount &&
                supplyAfter == supplyBefore
            );
        } else {
            assert(
                fromAfter == fromBefore &&
                toAfter == toBefore &&
                supplyAfter == supplyBefore
            );
        }

        assert(cBalanceAfter == cBalanceBefore);
    }
}

