contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value, address owner, address spender) public payable {
        require(true);

        // Read the underlying share token address, which is public immutable on C.
        address share = address(c.share());

        // Probe the underlying share token directly for the same transfer call.
        // We use a low-level call so that a revert of the share token does not abort this test.
        (bool expectedTransferSuccess, bytes memory expectedTransferData) =
            share.call(abi.encodeWithSignature("transfer(address,uint256)", to, value));

        // Now call c.transfer. This is the top-level state-changing call.
        bool transferReverted;
        bytes memory transferData;
        try c.transfer(to, value) returns (bool result) {
            transferReverted = false;
            transferData = abi.encode(result);
        } catch {
            transferReverted = true;
            transferData = "";
        }

        // Rule for transfer: reversion matches, and on success the returned bool matches
        // the bool returned by the underlying share token's transfer.
        bool transferBoolMatches = transferReverted
            ? true
            : (expectedTransferSuccess && abi.decode(transferData, (bool)) == abi.decode(expectedTransferData, (bool)));

        // Probe underlying approve.
        (bool expectedApproveSuccess,) =
            share.call(abi.encodeWithSignature("approve(address,uint256)", spender, value));

        bool approveReverted;
        try c.approve(spender, value) returns (bool result) {
            approveReverted = false;
        } catch {
            approveReverted = true;
        }

        bool approveRevertMatches = approveReverted == !expectedApproveSuccess;

        // Probe underlying transferFrom for an arbitrary owner/spender/value combination.
        (bool expectedTransferFromSuccess,) =
            share.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", owner, to, value));

        bool transferFromReverted;
        try c.transferFrom(owner, to, value) {
            transferFromReverted = false;
        } catch {
            transferFromReverted = true;
        }

        bool transferFromRevertMatches = transferFromReverted == !expectedTransferFromSuccess;

        assert(transferBoolMatches && approveRevertMatches && transferFromRevertMatches);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
