        }

        bool approveReverted;
        try c.approve(spender, value) {
            approveReverted = false;
        } catch {
            approveReverted = true;
        }

        bool transferFromReverted;
        try c.transferFrom(owner, to, value) {
            transferFromReverted = false;
        } catch {
            transferFromReverted = true;
        }

        // The pool forwards the exact msg.data plus its own address to the share token.
        // Since this test contract is the caller, the forwarded caller address is address(this).
        // Probe the underlying share token with the same forwarded call so we can compare outcomes.
        (bool expectedTransferSuccess, bytes memory expectedTransferData) =
            share.call(bytes.concat(abi.encodeWithSignature("transfer(address,uint256)", to, value), bytes20(address(this))));
        (bool expectedApproveSuccess, bytes memory expectedApproveData) =
            share.call(bytes.concat(abi.encodeWithSignature("approve(address,uint256)", spender, value), bytes20(address(this))));
        (bool expectedTransferFromSuccess, bytes memory expectedTransferFromData) =
            share.call(bytes.concat(abi.encodeWithSignature("transferFrom(address,address,uint256)", owner, to, value), bytes20(address(this))));

        bool transferRule = transferReverted == !expectedTransferSuccess;
        bool approveRule = approveReverted == !expectedApproveSuccess;
        bool transferFromRule = transferFromReverted == !expectedTransferFromSuccess;

        assert(transferRule && approveRule && transferFromRule);
    }

    receive() external payable {}
}

