    function run(address user, uint256 callerWardSeed, uint256 targetWardSeed) public payable {
        require(user != address(this), "test precondition: do not reuse caller/authorized account");

        // Use the given seeds only to choose a caller-nonzero or caller-zero scenario.
        // We do not touch c's wards directly; only rely/deny via auth on c.
        // Setup: if the caller should be unauthorized, we intentionally do nothing to it;
        // if authorized, we rely on the test contract itself only if needed.
        // Since the test contract is the deployer and thus initially authorized,
        // we can optionally deny then re-rely it to create both cases.
        if (callerWardSeed == 0) {
            c.deny(address(this));
        } else {
            c.rely(address(this));
        }

        uint256 callerWardBefore = c.wards(address(this));
        uint256 targetWardBefore = c.wards(user);

        bool relyReverted;
        try c.rely(user) {
            relyReverted = false;
        } catch {
            relyReverted = true;
        }

        uint256 targetWardAfter = c.wards(user);
        uint256 callerWardAfter = c.wards(address(this));

        assert(
            (callerWardBefore == 1)
                ? (!relyReverted && targetWardAfter == 1)
                : (relyReverted && targetWardAfter == targetWardBefore && callerWardAfter == callerWardBefore)
        );
    }

    receive() external payable {}
}

