contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, bool useRely) public {
        // Read the pre-state authorization status for the arbitrary user and for the caller.
        uint256 userBefore = c.wards(user);
        uint256 callerBefore = c.wards(address(this));

        // The test contract deployed c, so it is authorized. We take an arbitrary user
        // and, if they are not already authorized, rely/deny from this test contract
        // does not test the unauthorized path. Instead, use a fresh call from an
        // unauthorized perspective is not possible here since msg.sender is this test
        // contract. The verifiable rule is the auth invariant: only authorized callers
        // can change wards, and the contract's own authorization is established at deploy.
        bool reverted;
        if (useRely) {
            try c.rely(user) { reverted = false; } catch { reverted = true; }
        } else {
            try c.deny(user) { reverted = false; } catch { reverted = true; }
        }

        uint256 userAfter = c.wards(user);

        // General rule: since the test contract is authorized (deployed c), the call
        // must not revert, and the targeted user's authorization status must be set
        // to 1 for rely and 0 for deny. Also, the caller's own authorization must
        // remain 1 throughout.
        uint256 expected = useRely ? 1 : 0;
        bool callerStillAuthorized = c.wards(address(this)) == 1;
        assert(!reverted && userAfter == expected && callerStillAuthorized);
    }
}

