    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint128 newPrice) public payable {
        require(caller != address(0), "zero caller");
        c.rely(caller);

        uint128 priceBefore = c.latestPrice();
        uint256 timeBefore = c.lastPriceUpdate();

        bool reverted = false;
        try c.updatePrice(newPrice) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(c.wards(caller) == 1 && !reverted && c.latestPrice() == newPrice && c.lastPriceUpdate() == block.timestamp);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint128 newPrice) public payable {
        require(caller != address(0), "zero caller");
        require(caller != address(c), "cannot be c");
        require(caller != address(this), "cannot be test contract");

        c.rely(caller);

        uint128 priceBefore = c.latestPrice();
        uint256 timeBefore = c.lastPriceUpdate();
        bool callerIsWard = c.wards(caller) == 1;

        bool reverted = false;
        try c.updatePrice(newPrice) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (callerIsWard) {
            assert(!reverted && c.latestPrice() == newPrice && c.lastPriceUpdate() == block.timestamp);
        } else {
            assert(reverted && c.latestPrice() == priceBefore && c.lastPriceUpdate() == timeBefore);
        }
    }

    receive() external payable {}
}

