contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 amount) public {
        // Baseline: the test contract is the ward (it deployed c), while `user` is a generic address.
        require(user != address(this), "user must differ from the test contract");

        uint256 userWardBefore = c.wards(user);
        uint256 selfWardBefore = c.wards(address(this));

        // Non-ward attempts a full set of auth-gated state-changing calls.
        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }

        bool mintReverted;
        try c.mint(user, amount) { mintReverted = false; } catch { mintReverted = true; }

        bool burnReverted;
        try c.burn(user, amount) { burnReverted = false; } catch { burnReverted = true; }

        bool updatePriceReverted;
        try c.updatePrice(uint128(amount)) { updatePriceReverted = false; } catch { updatePriceReverted = true; }

        bool fileReverted;
        try c.file("investmentManager", user) { fileReverted = false; } catch { fileReverted = true; }

        // Every state-changing auth-gated function must reject a non-ward caller,
        // and must not mutate the ward mapping as a side effect of the failed call.
        assert(
            relyReverted && denyReverted && mintReverted && burnReverted && updatePriceReverted && fileReverted &&
                c.wards(user) == userWardBefore &&
                c.wards(address(this)) == selfWardBefore
        );
    }

    receive() external payable {}
}

