contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user) public {
        // caller must be an address that is already authorized (wards == 1);
        // otherwise rely/deny will revert. We cannot assume arbitrary initial
        // wards state, so we first rely the caller ourselves (we are the deployer
        // and thus authorized in the constructor).
        c.rely(caller);

        // Drive rely(user) as caller. This must succeed when caller is a ward.
        // To make the call as `caller` we cannot prank (no vm), so instead we
        // observe the state transition for the test contract's own address as
        // the caller. c.rely(user) from this contract is an authorized call
        // because this contract was relied in the constructor and its wards
        // value is 1.
        c.rely(user);

        // General rule: after an authorized rely(user), the wards mapping for
        // `user` must read 1.
        assert(c.wards(user) == 1);
    }
}

