contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 assets, uint256 shares) public payable {
        require(address(this).balance >= 0);

        address assetAddr = c.asset();
        TrancheTokenLike shareToken = c.share();
        InvestmentManagerLike im = c.investmentManager();

        require(assetAddr != address(0));
        require(address(shareToken) != address(0));
        require(address(im) != address(0));
        require(assets <= type(uint256).max / 2);
        require(shares <= type(uint256).max / 2);

        uint256 convertToSharesResult = c.convertToShares(assets);
        uint256 imConvertToSharesResult = im.convertToShares(assets, address(c));

        uint256 convertToAssetsResult = c.convertToAssets(shares);
        uint256 imConvertToAssetsResult = im.convertToAssets(shares, address(c));

        uint256 nameResult = bytes(c.name()).length;
        uint256 symbolResult = bytes(c.symbol()).length;

        uint8 decimalsResult = c.decimals();
        uint8 shareDecimalsResult = shareToken.decimals();

        uint256 totalSupplyResult = c.totalSupply();
        uint256 shareTotalSupplyResult = shareToken.totalSupply();

        uint256 balanceOfResult = c.balanceOf(user);
        uint256 shareBalanceOfResult = shareToken.balanceOf(user);

        uint256 allowanceResult = c.allowance(user, address(this));
        uint256 shareAllowanceResult = shareToken.allowance(user, address(this));

        uint256 maxDepositResult = c.maxDeposit(user);
        uint256 imMaxDepositResult = im.maxDeposit(user, address(c));

        uint256 maxMintResult = c.maxMint(user);
        uint256 imMaxMintResult = im.maxMint(user, address(c));

        uint256 maxWithdrawResult = c.maxWithdraw(user);
        uint256 imMaxWithdrawResult = im.maxWithdraw(user, address(c));

        uint256 maxRedeemResult = c.maxRedeem(user);
        uint256 imMaxRedeemResult = im.maxRedeem(user, address(c));

        assert(convertToSharesResult == imConvertToSharesResult);
        assert(convertToAssetsResult == imConvertToAssetsResult);
        assert(nameResult == bytes(shareToken.name()).length);
        assert(symbolResult == bytes(shareToken.symbol()).length);
        assert(decimalsResult == shareDecimalsResult);
        assert(totalSupplyResult == shareTotalSupplyResult);
        assert(balanceOfResult == shareBalanceOfResult);
        assert(allowanceResult == shareAllowanceResult);
        assert(maxDepositResult == imMaxDepositResult);
        assert(maxMintResult == imMaxMintResult);
        assert(maxWithdrawResult == imMaxWithdrawResult);
        assert(maxRedeemResult == imMaxRedeemResult);
    }

    receive() external payable {}
}

