    constructor(C _c) {
        c = _c;
    }

    function run(address caller, address user, uint256 value) public {
        bool initiallyWard = c.wards(caller) == 1;
        c.rely(caller);
        bool nowWard = c.wards(caller) == 1;

        bool reverted;
        if (nowWard) {
            try c.mint(user, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.mint(user, value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(nowWard ? true : reverted);
    }
}

