contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address user) public {
        require(user != address(0), "zero address");

        bool beforeIsWard = c.wards(user) == 1;
        bool relyReverted;
        try c.rely(user) { relyReverted = false; } catch { relyReverted = true; }

        if (!relyReverted) {
            assert(c.wards(user) == 1);
        } else {
            assert(c.wards(user) == (beforeIsWard ? 1 : 0));
        }

        bool denyReverted;
        try c.deny(user) { denyReverted = false; } catch { denyReverted = true; }

        if (!denyReverted) {
            assert(c.wards(user) == 0);
        } else {
            assert(c.wards(user) == 0);
        }
    }
}

