contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint128 newPrice, uint128 initialPrice) public payable {
        // Make the test contract a ward so it can call updatePrice.
        c.rely(address(this));

        // Establish a known price and timestamp before the deciding call.
        c.updatePrice(initialPrice);
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

        // The deciding call with a fresh input price.
        c.updatePrice(newPrice);

        // General rule: after an authorized update, the recorded price equals the
        // input and the recorded timestamp is at least the previous timestamp.
        // Also, the update must have actually changed/updated the stored price to the input,
        // independent of the prior value.
        assert(c.latestPrice() == newPrice && c.lastPriceUpdate() >= beforeTime && beforePrice == initialPrice);
    }

    receive() external payable {}
}

