    constructor(C _c) {
        c = _c;
    }

    function run(address user, uint256 which) public {
        require(user != address(0), "user is zero");
        require(which < 2, "invalid which");

        // Caller (this contract) is authorized in constructor.
        if (which == 0) {
            bool reverted;
            try c.rely(user) {
                reverted = false;
            } catch {
                reverted = true;
            }
            if (!reverted) {
                assert(c.wards(user) == 1);
            } else {
                assert(c.wards(user) == 0);
            }
        } else {
            // Grant first so deny has a chance to change state.
            c.rely(user);
            bool revertedDeny;
            try c.deny(user) {
                revertedDeny = false;
            } catch {
                revertedDeny = true;
            }
            if (!revertedDeny) {
                assert(c.wards(user) == 0);
            } else {
                assert(c.wards(user) == 1);
            }
        }
    }
}

